namespace MyFirstApp.Models
{
    public class Product
    {
        public int Id { get; set; }
        public string Name { get; set; } = string.Empty;
        public string Description { get; set; } = string.Empty;
        public decimal Price { get; set; }
        public int StockQuantity { get; set; }
        public bool IsAvailable => StockQuantity > 0;
        public DateTime CreatedAt { get; set; } = DateTime.UtcNow;

        // Computed property — no backing field needed
        public string DisplayPrice => Price.ToString("C");
    }
}

public class ProductsController : Controller
{
    private static readonly List<Product> _products = new()
    {
        new Product { Id = 1, Name = "Laptop", Price = 999.99m, StockQuantity = 15 },
        new Product { Id = 2, Name = "Coffee Mug", Price = 12.50m, StockQuantity = 100 }
    };

    public IActionResult Details(int id)
    {
        var product = _products.FirstOrDefault(p => p.Id == id);

        if (product == null)
        {
            return NotFound();
        }

        // Pass the Product object as the model
        return View(product);
    }
}

// In the controller
public IActionResult Details(int id)
{
    var product = _products.FirstOrDefault(p => p.Id == id);
    if (product == null) return NotFound();

    ViewData["PageTitle"] = $"Product: {product.Name}";
    ViewData["ShowBanner"] = true;

    return View(product);
}

<!-- In the view -->
<h2>@ViewData["PageTitle"]</h2>

@if ((bool)ViewData["ShowBanner"])
{
    <div class="banner">Special offer!</div>
}

// In the controller
public IActionResult Details(int id)
{
    var product = _products.FirstOrDefault(p => p.Id == id);
    if (product == null) return NotFound();

    ViewBag.PageTitle = $"Product: {product.Name}";
    ViewBag.ShowBanner = true;
    ViewBag.RelatedProducts = _products.Where(p => p.Id != id).Take(3);

    return View(product);
}

<!-- In the view -->
<h2>@ViewBag.PageTitle</h2>

@if (ViewBag.ShowBanner)
{
